import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import pwa from 'vite-plugin-pwa'
import { readFileSync } from 'fs'

const pkg = JSON.parse(readFileSync('./package.json'))

export default defineConfig({
