@import "tailwindcss";

@layer base {
  :root {
    --hue: 215;
    --sat: 85%;
    --light: 97%;
    --dark: 8%;
    --accent-hsl: var(--hue) var(--sat) var(--light);
    --accent-hsl-dark: var(--hue) var(--sat) var(--dark);
    --accent: hsl(var(--accent-hsl));
    --accent-dark: hsl(var(--accent-hsl-dark));
    --bg: hsl(var(--light));
    --bg-dark: hsl(var(--dark));
    --surface: hsl(210 15% 97%);
    --surface-dark: hsl(230 10% 12%);
    --text: hsl(240 10% 16%);
    --text-dark: hsl(220 10% 85%);
    --border: hsl(220 10% 90%);
    --border-dark: hsl(230 10% 25%);
    --success: hsl(142 71% 45%);
    --danger: hsl(348 100% 61%);
  }

  @media (prefers-color-scheme: dark) {
    :root {
      --bg: hsl(var(--dark));
      --bg-dark: hsl(var(--light));
      --surface: hsl(230 10% 12%);
      --surface-dark: hsl(210 15% 97%);
      --text: hsl(220 10% 85%);
      --text-dark: hsl(240 10% 16%);
      --border: hsl(230 10% 25%);
      --border-dark: hsl(220 10% 90%);
    }
  }
}

* {
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystem, "Segoe UI", "Roboto", "Helvetica Neue", sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  background: var(--bg);
  color: var(--text);
  transition: background 0.3s ease, color 0.3s ease;
}

export interface Habit {
  id: string
  name: string
  color: string
  emoji: string
  streak: number
  maxStreak: number
  createdAt: string
}

export interface HabitLog {
  id: string
  habitId: string
  completed: boolean
  date: string
}

export interface MoodEntry {
  id: string
  date: string
  value: 1 | 2 | 3 | 4 | 5
  note?: string
  createdAt: string
}

export interface ThemePreference {
  darkMode: boolean
}

import { openDatabase, type IDBPandas, type IDBPandasDatabase } from 'idb'

export interface AppDBSchema {
  habits: string
  habitLogs: string
  moods: string
  settings: string
}

const DB_NAME = 'rhythm-db'
const DB_VERSION = 1

export const db = openDatabase(DB_NAME, DB_VERSION, (upgradeDb) => {
  if (!upgradeDb.objectStoreNames.contains('habits')) {
    const habitsStore = upgradeDb.createObjectStore('habits', { keyPath: 'id' })
    habitsStore.createIndex('createdAt', 'createdAt')
  }

  if (!upgradeDb.objectStoreNames.contains('habitLogs')) {
    const logsStore = upgradeDb.createObjectStore('habitLogs', { keyPath: 'id' })
    logsStore.createIndex('habitId', 'habitId')
    logsStore.createIndex('date', 'date')
  }

  if (!upgradeDb.objectStoreNames.contains('moods')) {
    const moodsStore = upgradeDb.createObjectStore('moods', { keyPath: 'id' })
    moodsStore.createIndex('date', 'date')
  }

  if (!upgradeDb.objectStoreNames.contains('settings')) {
    const settingsStore = upgradeDb.createObjectStore('settings', { keyPath: 'id' })
    settingsStore.put({ id: 'theme', darkMode: false })
  }
})

export async function getHabits(): Promise<Habit[]> {
  return await db.table('habits').toArray()
}

export async function addHabit(habit: Omit<Habit, 'id' | 'streak' | 'maxStreak' | 'createdAt'>): Promise<string> {
  const id = crypto.randomUUID()
  const newHabit: Habit = {
    ...habit,
    id,
    streak: 0,
    maxStreak: 0,
    createdAt: new Date().toISOString(),
  }
  await db.table('habits').put(newHabit)
  return id
}

export async function updateHabit(habit: Habit): Promise<void> {
  await db.table('habits').put(habit)
}

export async function deleteHabit(id: string): Promise<void> {
  await db.table('habits').delete(id)
  await db.table('habitLogs').where('habitId').equals(id).delete()
}

export async function getHabitLogsByDate(date: string): Promise<HabitLog[]> {
  return await db.table('habitLogs').where('date').equals(date).toArray()
}

export async function logHabitCompleted(habitId: string, completed: boolean): Promise<void> {
  const date = formatDate(new Date())
  const existing = await db.table('habitLogs').where({ habitId, date }).first()

  if (existing) {
    await db.table('habitLogs').update(existing.id, { completed })
  } else {
    await db.table('habitLogs').put({
      id: crypto.randomUUID(),
      habitId,
      completed,
      date,
    })
  }

  await updateStreak(habitId, completed)
}

async function updateStreak(habitId: string, completed: boolean): Promise<void> {
  const habit = await db.table('habits').get(habitId)
  if (!habit) return

  const logs = await db.table('habitLogs').where('habitId').equals(habitId).toArray()
  const today = formatDate(new Date())
  const yesterday = formatDate(new Date(Date.now() - 86400000))

  // Find last completed log before today
  const yesterdayLog = logs.find(
    (log) => log.date === yesterday && log.completed
  )

  let streak = habit.streak
  if (completed) {
    if (yesterdayLog || streak === 0) {
      streak += 1
    } else {
      streak = 1
    }
  } else {
    streak = 0
  }

  const maxStreak = Math.max(habit.maxStreak, streak)

  await db.table('habits').update(habitId, { streak, maxStreak })
}

export async function getMoodForDate(date: string): Promise<MoodEntry | undefined> {
  return await db.table('moods').where('date').equals(date).first()
}

export async function setMood(value: 1 | 2 | 3 | 4 | 5, note?: string): Promise<void> {
  const date = formatDate(new Date())
  const existing = await db.table('moods').where('date').equals(date).first()

  if (existing) {
    await db.table('moods').update(existing.id, { value, note })
  } else {
    await db.table('moods').put({
      id: crypto.randomUUID(),
      date,
      value,
      note,
      createdAt: new Date().toISOString(),
    })
  }
}

export async function clearMoodForDate(date: string): Promise<void> {
  const existing = await db.table('moods').where('date').equals(date).first()
  if (existing) {
    await db.table('moods').delete(existing.id)
  }
}

export async function getThemePreference(): Promise<ThemePreference> {
  const settings = await db.table('settings').get('theme')
  return settings ?? { darkMode: false }
}

export async function setThemePreference(darkMode: boolean): Promise<void> {
  await db.table('settings').put({ id: 'theme', darkMode })
}

export function formatDate(date: Date): string {
  return date.toISOString().split('T')[0]
}

export function getWeekDates(): string[] {
  const dates: string[] = []
  const today = new Date()
  for (let i = 6; i >= 0; i--) {
    const d = new Date(today)
    d.setDate(d.getDate() - i)
    dates.push(formatDate(d))
  }
  return dates
}

import { useCallback } from 'react'
import * as idb from '../db'
import type { Habit, MoodEntry } from '../types'
