  const { habits } = React.useContext(HabitContext)

  const todayLogs = React.useMemo(() => {
    const date = idb.formatDate(new Date())
    return habits.map((habit) => ({
      habit,
      completed: false,
    }))
  }, [habits])

  const handleAddHabit = useCallback(() => {
    if (newHabitName.trim()) {
      idb.addHabit({
        name: newHabitName.trim(),
        color: newHabitColor,
        emoji: '🟡',
      }).then(() => {
        setNewHabitName('')
        setShowHabitModal(false)
      })
    }
  }, [newHabitName, newHabitColor])

  const handleHabitToggle = useCallback(
    async (habitId: string) => {
      const habit = habits.find((h) => h.id === habitId)
      if (habit) {
        // Toggle logic would be implemented in habit log
        // For now just log completion
      }
    },
    [habits]
  )

  const HabitContextValue = React.useMemo< HabitsContextValue>(
    () => ({
      habits,
